        "transitions": (transitions or []) + [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}],
    }


def cond_any(*pairs):
    return {"logic": "or", "conditions": [{"variable": v, "operator": "equals", "operand": o} for v, o in pairs]}


