nodes["opening"] = conv(
    "opening", OPENING_TASK, [T_CLOSE, T_TRANSFER],
    [CLOSED,
     {"target_node": "identity", "description": "The person confirmed they are the customer",
      "condition": cond_any(("speaker", "confirmed"))},
