    return WD[d.weekday()] + ' ' + str(d.day) + ' ' + MO[d.month-1] + ' ' + str(d.year)
def money(x):
    x = float(x)
    if abs(x - round(x)) < 0.005:
        return format(int(round(x)), ',')
    return format(x, ',.2f')
def find_products():
    p = vars.get('products')
    if isinstance(p, str):
