            p = json.loads(p)
        except Exception:
            p = None
    if isinstance(p, dict) and 'products' in p:
        p = p.get('products')
    if isinstance(p, list) and p:
        return p
    for k in list(vars.keys()):
        v = vars.get(k)
        if k.endswith('products') and k != 'products':
            if isinstance(v, str):
                try:
                    v = json.loads(v)
                except Exception:
                    v = None
