    return [rows[i] for i in sorted(rows)]
def nth_bd(today, n):
    d = today; c = 0
    while c < n:
        d = d + datetime.timedelta(days=1)
        if bd(d): c += 1
    return d
def next_bd_on_or_after(d):
    while not bd(d): d = d + datetime.timedelta(days=1)
    return d
try:
